                    /// <summary>There is no effect or the effect is indescribable.</summary>
                    NONE = 0,
                    /// <summary>The element is set or otherwise mutated.</summary>
                    SET = 1,
                    /// <summary>An alias to the element is returned.</summary>
                    ALIAS = 2,
